// The 3D avatar renderer (task 5.2). Loaded lazily (dynamic import) so Three.js never blocks the page.
// Bodies follow the account's avatar_gender setting; fitted garments come per body, point accessories hang on
// the body's attachment points (manifest v2, generated by scripts/make-avatar-models.mjs).
import {ACESFilmicToneMapping, CircleGeometry, Color, DirectionalLight, Group, HemisphereLight, Mesh, MeshPhysicalMaterial,
  PCFSoftShadowMap, PMREMGenerator, PerspectiveCamera, Scene, ShadowMaterial, WebGLRenderer, type Material, type Object3D} from 'three';
import {GLTFLoader} from 'three/examples/jsm/loaders/GLTFLoader.js';
import {MeshoptDecoder} from 'three/examples/jsm/libs/meshopt_decoder.module.js';
import {RoomEnvironment} from 'three/examples/jsm/environments/RoomEnvironment.js';

export type Slot = {template: string; anchor?: 'body' | 'point'; capacity: number; positions: string[]};
/** base: the default modest layer (tank and boxer-briefs) worn whenever no underwear is equipped. */
export type Manifest = {bodies: Record<string, string>; base?: string; slots: Record<string, Slot>};
export type Worn = {slot: string; index: number; colour: string};
export type AvatarScene = {
  show: (worn: Worn[]) => Promise<void>;
  setBody: (body: string) => Promise<void>;
  rotate: (radians: number) => void;
  zoom: (delta: number) => void;
  /** Frames the whole body, or the head and shoulders. */
  frame: (view: 'body' | 'face') => void;
  /** Spins continuously (the frame-rate route); returns a stop function. */
  spin: (radiansPerSecond: number) => () => void;
  onFrame: (cb: (ms: number) => void) => () => void;
  dispose: () => void;
};

const base = () => `${import.meta.env.BASE_URL}avatar/`;
const METAL = new Set(['ring', 'earrings', 'necklace', 'wrist', 'accessory', 'eyewear']);

/** Fabric reads as fabric (soft sheen, no gloss); shoes and belts a little polished; small hardware as metal. */
function garmentMaterial(slot: string, colour: string): Material {
  const color = new Color(colour);
  if (METAL.has(slot)) return new MeshPhysicalMaterial({color, metalness: 0.75, roughness: 0.28});
  if (slot === 'footwear' || slot === 'belt' || slot === 'bag') return new MeshPhysicalMaterial({color, roughness: 0.5, clearcoat: 0.25, clearcoatRoughness: 0.5});
  return new MeshPhysicalMaterial({color, roughness: 0.86, sheen: 0.6, sheenRoughness: 0.7, sheenColor: color.clone().lerp(new Color('#ffffff'), 0.35)});
}
/** The template file for this slot on this body ('{body}' marks a template fitted per body). */
export const templateFor = (slot: Slot, body: string) => slot.template.replace('{body}', body);

export async function createAvatarScene(canvas: HTMLCanvasElement, body: string): Promise<AvatarScene> {
  const manifest = await fetch(`${base()}manifest.json`).then(r => { if (!r.ok) throw new Error('avatar manifest ' + r.status); return r.json() as Promise<Manifest>; });
  const renderer = new WebGLRenderer({canvas, antialias: true, alpha: true, powerPreference: 'low-power'});
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.toneMapping = ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = PCFSoftShadowMap;
  const scene = new Scene();
  const pmrem = new PMREMGenerator(renderer);
  const room = new RoomEnvironment();
  scene.environment = pmrem.fromScene(room, 0.04).texture;
  scene.environmentIntensity = 0.45;
  room.dispose(); pmrem.dispose();

  const camera = new PerspectiveCamera(28, 1, 0.1, 20);
  let distance = 4.3;
  let aimY = 0.9;
  const place = () => { camera.position.set(0, aimY + 0.1 * distance / 4.3, distance); camera.lookAt(0, aimY, 0); };
  place();
  // Studio lighting: warm key with soft shadow, cool rim to separate the silhouette, low fill from the floor.
  scene.add(new HemisphereLight(0xfff4ee, 0x3a2433, 0.55));
  const key = new DirectionalLight(0xffeee2, 2.4);
  key.position.set(1.6, 3.2, 2.4); key.castShadow = true;
  key.shadow.mapSize.set(1024, 1024); key.shadow.radius = 4; key.shadow.bias = -0.0004; key.shadow.normalBias = 0.02;
  Object.assign(key.shadow.camera, {left: -1, right: 1, top: 2.1, bottom: -0.2, near: 0.5, far: 8});
  const rim = new DirectionalLight(0xd9c6ff, 1.6); rim.position.set(-2, 2.2, -2.4);
  const fill = new DirectionalLight(0xffd9e6, 0.35); fill.position.set(-1.5, 0.4, 2);
  scene.add(key, rim, fill);
  const ground = new Mesh(new CircleGeometry(1.1, 64), new ShadowMaterial({opacity: 0.28}));
  ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);

  const rig = new Group(); scene.add(rig);
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const cache = new Map<string, Promise<Object3D>>();
  const model = (file: string) => {
    if (!cache.has(file)) cache.set(file, loader.loadAsync(base() + file).then(g => g.scene));
    return cache.get(file)!.then(s => s.clone(true));
  };
  const shade = (o: Object3D) => o.traverse(n => { if ((n as Mesh).isMesh) { n.castShadow = true; n.receiveShadow = true; } });
  // Skin keeps its painted vertex colours (lips, brows) with a soft sheen; hair gets a fibre-like sheen.
  const dress = (o: Object3D) => o.traverse(n => {
    const m = n as Mesh; if (!m.isMesh) return;
    const name = (m.material as Material).name;
    if (name === 'skin') m.material = new MeshPhysicalMaterial({name, vertexColors: true, roughness: 0.58, sheen: 0.35, sheenRoughness: 0.6, sheenColor: new Color('#ffd6c4')});
    if (name === 'hair') m.material = new MeshPhysicalMaterial({name, color: (m.material as MeshPhysicalMaterial).color, roughness: 0.55, sheen: 0.8, sheenRoughness: 0.35, sheenColor: new Color('#8a6a5a')});
  });
  let bodyKey = '';
  let bodyNode: Object3D | null = null;
  const garments = new Group(); rig.add(garments);
  let worn: Worn[] = [];
  let generation = 0;

  const resize = () => {
    const {clientWidth: w, clientHeight: h} = canvas;
    if (!w || !h) return;
    renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
  };
  const frameListeners = new Set<(ms: number) => void>();
  let raf = 0, last = performance.now(), spinRate = 0, dirty = true;
  const loop = (now: number) => {
    raf = requestAnimationFrame(loop);
    const dt = now - last; last = now;
    if (spinRate) { rig.rotation.y += spinRate * dt / 1000; dirty = true; }
    if (!dirty && !frameListeners.size) return;
    resize(); renderer.render(scene, camera); dirty = false;
    for (const l of frameListeners) l(dt);
  };
  raf = requestAnimationFrame(loop);

  const attach = async () => {
    const mine = ++generation;
    if (!bodyNode) return;
    const next = await Promise.all(worn.map(async w => {
      const spec = manifest.slots[w.slot];
      if (!spec) return null;
      const garment = await model(templateFor(spec, bodyKey));
      const material = garmentMaterial(w.slot, w.colour);
      garment.traverse(o => { if ((o as Mesh).isMesh) (o as Mesh).material = material; });
      if (spec.anchor !== 'body') {
        const point = bodyNode!.getObjectByName(spec.positions[Math.min(w.index, spec.positions.length - 1)]!);
        if (point) garment.position.copy(point.position);
      }
      shade(garment);
      return garment;
    }));
    if (manifest.base && !worn.some(w => w.slot === 'underwear')) {
      const base = await model(manifest.base.replace('{body}', bodyKey));
      base.traverse(o => { const m = o as Mesh; if (m.isMesh) m.material = garmentMaterial('base', '#' + (m.material as MeshPhysicalMaterial).color.getHexString()); });
      const covered = new Set(worn.map(w => w.slot));
      const hide = {'base-top': ['top', 'outer', 'dress'], 'base-bottom': ['bottom', 'dress']} as const;
      for (const [part, by] of Object.entries(hide)) { const n = base.getObjectByName(part); if (n) n.visible = !by.some(b => covered.has(b)); }
      shade(base); next.push(base);
    }
    if (mine !== generation) return;                 // a newer look or body arrived while these loaded
    garments.clear();
    for (const g of next) if (g) garments.add(g);
    dirty = true;
  };
  const setBody = async (b: string) => {
    const key = b in manifest.bodies ? b : Object.keys(manifest.bodies)[0]!;
    if (key === bodyKey && bodyNode) return;
    const next = await model(manifest.bodies[key]!);
    dress(next); shade(next);
    if (bodyNode) rig.remove(bodyNode);
    bodyKey = key; bodyNode = next; rig.add(next);
    await attach();
  };
  await setBody(body);
  return {
    show: async next => { worn = next; await attach(); },
    setBody,
    rotate: r => { rig.rotation.y += r; dirty = true; },
    zoom: d => { distance = Math.min(7, Math.max(2.2, distance + d)); place(); dirty = true; },
    frame: view => { if (view === 'face') { distance = 0.75; aimY = 1.53; } else { distance = 4.3; aimY = 0.9; } place(); dirty = true; },
    spin: rate => { spinRate = rate; return () => { spinRate = 0; }; },
    onFrame: cb => { frameListeners.add(cb); return () => frameListeners.delete(cb); },
    dispose: () => { cancelAnimationFrame(raf); scene.environment?.dispose(); renderer.dispose(); scene.clear(); },
  };
}
